(()=>{
 const key='terra-position-v2', size=44, margin=20;
 const orb=document.createElement('button');orb.type='button';orb.className='terra-floating-orb';orb.setAttribute('aria-label','Abrir TERRA. Arrastra para mover; usa las flechas del teclado para ajustar su posición.');orb.setAttribute('aria-expanded','false');orb.title='Abrir TERRA · Arrastra para mover';
 orb.innerHTML=`<svg viewBox="0 0 24 24" aria-hidden="true"><rect class="terra-bar b1" x="5" y="7" width="3.2" height="10" rx="2" fill="#F5A623"/><rect class="terra-bar b2" x="10.4" y="4" width="3.2" height="16" rx="2" fill="#00C6FF"/><rect class="terra-bar b3" x="15.8" y="8" width="3.2" height="8" rx="2" fill="#F5A623"/></svg>`;
 const style=document.createElement('style');style.textContent=`.terra-floating-orb{position:fixed;z-index:2147483000;width:${size}px;height:${size}px;padding:10px;border:0;border-radius:50%;background:rgba(7,19,31,.84);backdrop-filter:blur(12px);-webkit-backdrop-filter:blur(12px);cursor:grab;touch-action:none;box-shadow:0 8px 24px rgba(0,0,0,.42);transition:transform .25s ease,box-shadow .25s ease}.terra-floating-orb::before{content:'';position:absolute;inset:0;border-radius:50%;padding:1px;background:linear-gradient(135deg,rgba(245,166,35,.65),rgba(0,198,255,.65));-webkit-mask:linear-gradient(#fff 0 0) content-box,linear-gradient(#fff 0 0);-webkit-mask-composite:xor;mask-composite:exclude;pointer-events:none;transition:opacity .25s ease;opacity:.85}.terra-floating-orb svg{display:block;width:100%;height:100%}.terra-floating-orb:hover,.terra-floating-orb[aria-expanded=true]{transform:translateY(-1px);box-shadow:0 10px 28px rgba(0,198,255,.18)}.terra-floating-orb:hover::before,.terra-floating-orb[aria-expanded=true]::before{opacity:1}.terra-floating-orb:active{cursor:grabbing}.terra-floating-orb:focus-visible{outline:2px solid #00C6FF;outline-offset:3px}.terra-bar{transform-origin:center;transition:transform .25s ease}.terra-floating-orb:hover .terra-bar,.terra-floating-orb[aria-expanded=true] .terra-bar{animation:terra-wave 1.3s ease-in-out infinite}.terra-floating-orb:hover .b2,.terra-floating-orb[aria-expanded=true] .b2{animation-delay:.18s}.terra-floating-orb:hover .b3,.terra-floating-orb[aria-expanded=true] .b3{animation-delay:.36s}@keyframes terra-wave{0%,100%{transform:scaleY(1)}50%{transform:scaleY(.62)}}@media(prefers-reduced-motion:reduce){.terra-floating-orb,.terra-bar{animation:none!important;transition:none}}`;document.head.append(style);document.body.append(orb);
 const frame=document.createElement('iframe');frame.title='Asistente TERRA';frame.src='/terra/';frame.hidden=true;frame.style.cssText='position:fixed;border:0;background:transparent;z-index:2147482999;';document.body.append(frame);
 let x=innerWidth-size-20,y=innerHeight-size-20,drag=null,moved=false,opened=false,panelHeight=520;
 const clamp=()=>{x=Math.max(margin,Math.min(x,Math.max(margin,innerWidth-size-margin)));y=Math.max(margin,Math.min(y,Math.max(margin,innerHeight-size-margin)))};
 function place(){clamp();orb.style.left=x+'px';orb.style.top=y+'px';if(opened){const w=Math.min(370,innerWidth-16),h=Math.min(panelHeight,innerHeight-16);frame.style.width=w+'px';frame.style.height=h+'px';frame.style.left=Math.max(8,Math.min(innerWidth-w-8,x+size-w))+'px';let top=y-h-8;if(top<8)top=y+size+8;if(top+h>innerHeight-8)top=Math.max(8,innerHeight-h-8);frame.style.top=top+'px'}}
 try{const p=JSON.parse(localStorage.getItem(key));if(p&&Number.isFinite(p.x)&&Number.isFinite(p.y)){x=p.x*Math.max(0,innerWidth-size);y=p.y*Math.max(0,innerHeight-size)}}catch{}
 function save(){try{localStorage.setItem(key,JSON.stringify({x:x/Math.max(1,innerWidth-size),y:y/Math.max(1,innerHeight-size)}))}catch{}}
 orb.addEventListener('pointerdown',e=>{if(e.button!==0)return;drag={px:e.clientX,py:e.clientY,x,y};moved=false;orb.setPointerCapture(e.pointerId)});
 orb.addEventListener('pointermove',e=>{if(!drag)return;const dx=e.clientX-drag.px,dy=e.clientY-drag.py;if(Math.hypot(dx,dy)>5)moved=true;if(moved){x=drag.x+dx;y=drag.y+dy;place()}});
 orb.addEventListener('pointerup',()=>{if(drag&&moved)save();drag=null});orb.addEventListener('pointercancel',()=>{drag=null});
 orb.addEventListener('click',()=>{if(moved){moved=false;return}if(opened){frame.hidden=true;opened=false;orb.setAttribute('aria-expanded','false');return}opened=true;frame.hidden=false;place();orb.setAttribute('aria-expanded','true');frame.contentWindow.postMessage({terraOpen:true},location.origin)});
 orb.addEventListener('keydown',e=>{const d= e.shiftKey?30:10;if(e.key==='ArrowLeft')x-=d;else if(e.key==='ArrowRight')x+=d;else if(e.key==='ArrowUp')y-=d;else if(e.key==='ArrowDown')y+=d;else return;e.preventDefault();place();save()});
 window.addEventListener('message',e=>{if(e.origin!==location.origin||e.source!==frame.contentWindow)return;if(Number.isFinite(e.data?.terraHeight))return;if(typeof e.data?.terraPanel!=='boolean')return;if(!e.data.terraPanel){opened=false;frame.hidden=true;orb.setAttribute('aria-expanded','false');orb.focus()}});window.addEventListener('keydown',e=>{if(e.key==='Escape'&&opened){opened=false;frame.hidden=true;orb.setAttribute('aria-expanded','false');orb.focus()}});window.addEventListener('resize',()=>{if(!localStorage.getItem(key)){x=innerWidth-size-20;y=innerHeight-size-20}place()});place();if('serviceWorker'in navigator){navigator.serviceWorker.register('/sw.js').catch(()=>{})}
})();
